const expireAccessRequests = `-- name: ExpireAccessRequests :many
UPDATE access_requests SET status = 'expired', decided_at = ?, decided_by = 'agent-office'
WHERE agent_id = ? AND status = 'pending'
RETURNING id, agent_id, kind, value, reason, status, created_at, decided_at, decided_by, decider_agent_id, decision_reason, scope
`

type ExpireAccessRequestsParams struct {
	DecidedAt sql.NullTime
	AgentID   string
}

func (q *Queries) ExpireAccessRequests(ctx context.Context, arg ExpireAccessRequestsParams) ([]AccessRequest, error) {
	rows, err := q.db.QueryContext(ctx, expireAccessRequests, arg.DecidedAt, arg.AgentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AccessRequest{}
	for rows.Next() {
		var i AccessRequest
		if err := rows.Scan(
			&i.ID,
			&i.AgentID,
			&i.Kind,
			&i.Value,
			&i.Reason,
			&i.Status,
			&i.CreatedAt,
			&i.DecidedAt,
			&i.DecidedBy,
			&i.DeciderAgentID,
			&i.DecisionReason,
			&i.Scope,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

