const upsertPullRequest = `-- name: UpsertPullRequest :one
INSERT INTO pull_requests (project_id, task_id, agent_id, branch, created_at, updated_at)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (project_id, branch) DO UPDATE SET updated_at = excluded.updated_at
RETURNING id, project_id, task_id, agent_id, branch, base, number, url, state, head, checks, failed_checks, pending_flagged, accepted_flagged, rounds, error, created_at, updated_at, conflict_rounds
`

type UpsertPullRequestParams struct {
	ProjectID string
	TaskID    sql.NullString
	AgentID   string
	Branch    string
	CreatedAt time.Time
	UpdatedAt time.Time
}

// Get-or-create the row for a branch; an existing row keeps its state and number.
func (q *Queries) UpsertPullRequest(ctx context.Context, arg UpsertPullRequestParams) (PullRequest, error) {
	row := q.db.QueryRowContext(ctx, upsertPullRequest,
		arg.ProjectID,
		arg.TaskID,
		arg.AgentID,
		arg.Branch,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	var i PullRequest
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.TaskID,
		&i.AgentID,
		&i.Branch,
		&i.Base,
		&i.Number,
		&i.Url,
		&i.State,
		&i.Head,
		&i.Checks,
		&i.FailedChecks,
		&i.PendingFlagged,
		&i.AcceptedFlagged,
		&i.Rounds,
		&i.Error,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ConflictRounds,
	)
	return i, err
}

const upsertUsage = `-- name: UpsertUsage :exec

INSERT INTO usage_messages (session_id, agent_id, task_id, source, message_id, request_id, model, speed,
    inference_geo, input_tokens, output_tokens, cache_read, cache_write_5m, cache_write_1h, at, updated_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (session_id, message_id) DO UPDATE SET
    request_id = CASE WHEN excluded.request_id != '' THEN excluded.request_id ELSE usage_messages.request_id END,
    model = excluded.model, speed = excluded.speed, inference_geo = excluded.inference_geo,
    input_tokens = excluded.input_tokens, output_tokens = excluded.output_tokens,
    cache_read = excluded.cache_read, cache_write_5m = excluded.cache_write_5m,
    cache_write_1h = excluded.cache_write_1h, updated_at = excluded.updated_at
`

type UpsertUsageParams struct {
	SessionID    string
	AgentID      string
	TaskID       sql.NullString
	Source       string
	MessageID    string
	RequestID    string
	Model        string
	Speed        string
	InferenceGeo string
	InputTokens  int64
	OutputTokens int64
	CacheRead    int64
	CacheWrite5m int64
	CacheWrite1h int64
	At           time.Time
	UpdatedAt    time.Time
}

// Token usage (migration 0007, ADR 0026).
func (q *Queries) UpsertUsage(ctx context.Context, arg UpsertUsageParams) error {
	_, err := q.db.ExecContext(ctx, upsertUsage,
		arg.SessionID,
		arg.AgentID,
		arg.TaskID,
		arg.Source,
		arg.MessageID,
		arg.RequestID,
		arg.Model,
		arg.Speed,
		arg.InferenceGeo,
		arg.InputTokens,
		arg.OutputTokens,
		arg.CacheRead,
		arg.CacheWrite5m,
		arg.CacheWrite1h,
		arg.At,
		arg.UpdatedAt,
	)
	return err
}
